## Решение на Python

Центр кластера – точка с минимальной суммой квадратов расстояний до остальных точек кластера. Границы кластеров подобраны визуально из диаграммы.

```python
def dist_sq(p1, p2):
    return (p2[0] - p1[0])**2 + (p2[1] - p1[1])**2

def find_center(points):
    if not points:
        return None
    min_sum = float('inf')
    best = None
    for cand in points:
        s = sum(dist_sq(cand, p) for p in points)
        if s < min_sum:
            min_sum = s
            best = cand
    return best

def process_file(path, clusters):
    stars = []
    with open(path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) >= 2:
                try:
                    x = float(parts[0].replace(',', '.'))
                    y = float(parts[1].replace(',', '.'))
                    stars.append((x, y))
                except:
                    pass
    cl = [[] for _ in range(clusters)]
    if 'A' in path:
        for x, y in stars:
            if y < -7:
                cl[0].append((x, y))
            elif 11 < x < 34 and -5 < y < 11:
                cl[1].append((x, y))
            else:
                cl[2].append((x, y))
    else:  # файл Б
        for x, y in stars:
            if y < -5:
                cl[0].append((x, y))
            elif y < x + 1:
                cl[1].append((x, y))
            elif y < 2*x + 11:
                cl[2].append((x, y))
            elif y < 13*x + 120:
                cl[3].append((x, y))
            elif y > -2.5*x - 30:
                cl[4].append((x, y))
            else:
                cl[5].append((x, y))
    centers = [find_center(c) for c in cl if c]
    cx = sum(c[0] for c in centers) / len(centers)
    cy = sum(c[1] for c in centers) / len(centers)
    return cx, cy

# Файл А
cx_a, cy_a = process_file('task27_18_A.txt', 3)
print(int(abs(cx_a)*10000), int(abs(cy_a)*10000))
# Файл Б
